test('checkout charges VAT and marks the cart paid', async () => {
  const repo = new InMemoryCartRepo([
    { id: 'c1', subtotalCents: 1000, country: 'GB', status: 'open' },
  ])
  const receipt = await checkout(repo, 'c1')
  expect(receipt.totalCents).toBe(1200) // 20% standard UK VAT
  expect((await repo.get('c1'))?.status).toBe('paid')
})

class FakeClock:
    def __init__(self, start: float) -> None:
        self.now = start

    def time(self) -> float:
        return self.now

    def advance(self, seconds: float) -> None:
        self.now += seconds


def test_token_expires_after_ttl():
    clock = FakeClock(start=1_000.0)
    token = issue_token(ttl_seconds=60, clock=clock)
    clock.advance(59)
    assert not is_expired(token, clock=clock)
    clock.advance(2)
    assert is_expired(token, clock=clock)

