class InMemoryCartRepo implements CartRepo {
  private carts = new Map<string, Cart>()
  constructor(seed: Cart[] = []) {
    for (const c of seed) this.carts.set(c.id, { ...c })
  }
  async get(id: string) { return this.carts.get(id) }
  async save(cart: Cart) { this.carts.set(cart.id, { ...cart }) }
}

